def transform(grid):
    h, w = len(grid), len(grid[0])
    base = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if not base:
        return [row[:] for row in grid]

    minr = min(r for r, c in base)
    minc = min(c for r, c in base)
    base = [(r - minr, c - minc) for r, c in base]
    bh = max(r for r, c in base) + 1
    bw = max(c for r, c in base) + 1

    # Generate the eight rotations/reflections, keeping identity first.
    variants = []
    for flip in (False, True):
        for turns in range(4):
            pts = [(r, bw - 1 - c if flip else c) for r, c in base]
            ph, pw = bh, bw
            for _ in range(turns):
                pts = [(c, ph - 1 - r) for r, c in pts]
                ph, pw = pw, ph
            mr = min(r for r, c in pts)
            mc = min(c for r, c in pts)
            pts = frozenset((r - mr, c - mc) for r, c in pts)
            if pts not in [v[0] for v in variants]:
                variants.append((pts, ph, pw))

    out = [row[:] for row in grid]
    colors = sorted({grid[r][c] for r in range(h) for c in range(w)} - {1, 4})
    threshold = max(bh, bw) + 1

    for color in colors:
        pixels = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Split widely separated same-color copies into separate groups.
        groups = []
        while pixels:
            group = [pixels.pop()]
            changed = True
            while changed:
                changed = False
                rest = []
                for p in pixels:
                    if any(max(abs(p[0] - q[0]), abs(p[1] - q[1])) <= threshold for q in group):
                        group.append(p)
                        changed = True
                    else:
                        rest.append(p)
                pixels = rest
            groups.append(group)

        for group in groups:
            best = None
            for oi, (shape, sh, sw) in enumerate(variants):
                anchors = set()
                for r, c in group:
                    for sr, sc in shape:
                        anchors.add((r - sr, c - sc))
                for ar, ac in anchors:
                    covered = sum((r - ar, c - ac) in shape for r, c in group)
                    center_dist = (
                        (2 * ar + sh - 1 - (min(r for r, c in group) + max(r for r, c in group))) ** 2
                        + (2 * ac + sw - 1 - (min(c for r, c in group) + max(c for r, c in group))) ** 2
                    )
                    rank = (covered, -oi, -center_dist)
                    if best is None or rank > best[0]:
                        best = (rank, ar, ac, shape)

            if best:
                _, ar, ac, shape = best
                for sr, sc in shape:
                    rr, cc = ar + sr, ac + sc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color

    return out
